        // Right child bounds
        real3<T> rightMin = prefixMin[numBins];
        real3<T> rightMax = prefixMax[numBins];
        int rightCount = prefixCount[numBins] - leftCount;

        // Calculate surface areas
        T leftSA = calculateSurfaceArea(leftMin, leftMax);
        T rightSA = calculateSurfaceArea(rightMin, rightMax);

        // Calculate cost
        T cost = leftCount * leftSA + rightCount * rightSA;

        if (cost < minCost) {
            minCost = cost;
            bestAxis = axis;
            bestPos = (axisMin + axisMax) * T(0.5); // midpoint of axis range
        }
    }
}

